input.command:
cd /tmp && mkdir -p ptest && cd ptest && cat > d.v <<'EOF'
module dut #(parameter WIDTH = 4) ();
  initial $display("DUT WIDTH %0d", WIDTH);
endmodule
EOF
cat > top.v <<'EOF'
`timescale 1ns/1ps
module top;
  dut #(.WIDTH(6)) U_DUT ();
  parameter DEPTH = 2;
  initial begin
    $display("TOP DEPTH %0d", DEPTH);
    #5 $finish;
  end
endmodule
EOF
iverilog -g2012 -o sim.vvp -s top -Ptop.DEPTH=9 -Ptop.U_DUT.WIDTH=12 d.v top.v && vvp -n sim.vvp

cd /tmp/ptest && cat > top3.v <<'EOF'
`timescale 1ns/1ps
module top;
  dut U_DUT ();
  defparam U_DUT.WIDTH = 12;
  initial begin
    #5 $finish;
  end
endmodule
EOF
iverilog -g2012 -o sim5.vvp -s top d.v top3.v && vvp -n sim5.vvp
echo "--- -P on root module param ---"
cat > top4.v <<'EOF'
`timescale 1ns/1ps
module top;
  parameter WIDTH = 4;
  initial begin
    $display("W %0d", WIDTH);
    #5 $finish;
  end
endmodule
EOF
iverilog -g2012 -o sim6.vvp -s top -Ptop.WIDTH=16 top4.v && vvp -n sim6.vvp
echo "--- bad param name on root ---"
iverilog -g2012 -o sim7.vvp -s top -Ptop.NOPE=16 top4.v; echo "rc=$?"

cd /tmp/ptest && cat > top5.v <<'EOF'
`timescale 1ns/1ps
module top;
  dut U_DUT ();
  defparam top.U_DUT.WIDTH = 12;
  initial #5 $finish;
endmodule
EOF
iverilog -g2012 -o simA.vvp -s top d.v top5.v && vvp -n simA.vvp
echo "=== nested two levels ==="
cat > d2.v <<'EOF'
module inner #(parameter W = 1) ();
  initial $display("INNER W %0d", W);
endmodule
module mid #(parameter W = 2) ();
  inner #(.W(W)) u_inner ();
endmodule
EOF
cat > top6.v <<'EOF'
`timescale 1ns/1ps
module top;
  mid #(.W(3)) u_mid ();
  initial #5 $finish;
endmodule
EOF
iverilog -g2012 -o simB.vvp -s top -Ptop.u_mid.W=7 d2.v top6.v && vvp -n simB.vvp
